-- Christmas Together — Tacoma 2026. Isolated tables; public submissions are pending until moderator approval.
create table if not exists public.hub_christmas_2026_submissions(id uuid primary key default gen_random_uuid(),campaign_slug text not null default 'christmas-2026' check(campaign_slug='christmas-2026'),category text not null check(category in('story','photo','video','light','business','event','giving','wish','challenge')),display_name text not null check(char_length(trim(display_name)) between 2 and 80),title text not null check(char_length(trim(title)) between 2 and 140),message text not null check(char_length(trim(message)) between 10 and 1800),area text check(area is null or char_length(area)<=100),url text check(url is null or(char_length(url)<=1000 and url ~* '^https://')),location_text text check(location_text is null or char_length(location_text)<=240),map_lat double precision check(map_lat is null or map_lat between 45 and 49),map_lng double precision check(map_lng is null or map_lng between -124 and -121),allow_precise_map boolean not null default false,verification_status text not null default 'not-applicable' check(verification_status in('not-applicable','needs-review','verified','expired')),allow_hub_display boolean not null default false,allow_tacoma_nights boolean not null default false,allow_social boolean not null default false,guardian_consent boolean not null default false,status text not null default 'pending' check(status in('pending','approved','rejected','archived')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now(),check(allow_hub_display=true),check(category<>'light' or map_lat is null or allow_precise_map));
create table if not exists public.hub_christmas_2026_contacts(submission_id uuid primary key references public.hub_christmas_2026_submissions(id) on delete cascade,email text not null check(char_length(email)<=254 and position('@' in email)>1),contact_permission boolean not null default false check(contact_permission=true),created_at timestamptz not null default now());
create index if not exists hub_christmas_2026_public_idx on public.hub_christmas_2026_submissions(campaign_slug,status,category,created_at desc);
alter table public.hub_christmas_2026_submissions enable row level security;
alter table public.hub_christmas_2026_contacts enable row level security;
drop policy if exists "Public submit Christmas Together contributions" on public.hub_christmas_2026_submissions;
create policy "Public submit Christmas Together contributions" on public.hub_christmas_2026_submissions for insert to anon,authenticated with check(status='pending' and reviewed_by is null and reviewed_at is null and allow_hub_display=true and verification_status='not-applicable' and map_lat is null and map_lng is null and allow_precise_map=false);
drop policy if exists "Public read approved Christmas Together contributions" on public.hub_christmas_2026_submissions;
create policy "Public read approved Christmas Together contributions" on public.hub_christmas_2026_submissions for select to anon,authenticated using(status='approved' and allow_hub_display=true and (category<>'giving' or verification_status='verified'));
drop policy if exists "Hub moderators manage Christmas Together contributions" on public.hub_christmas_2026_submissions;
create policy "Hub moderators manage Christmas Together contributions" on public.hub_christmas_2026_submissions for all to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator')));
drop policy if exists "Public provide private Christmas contact" on public.hub_christmas_2026_contacts;
create policy "Public provide private Christmas contact" on public.hub_christmas_2026_contacts for insert to anon,authenticated with check(contact_permission=true);
drop policy if exists "Hub moderators read private Christmas contacts" on public.hub_christmas_2026_contacts;
create policy "Hub moderators read private Christmas contacts" on public.hub_christmas_2026_contacts for select to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator')));
drop policy if exists "Hub moderators manage private Christmas contacts" on public.hub_christmas_2026_contacts;
create policy "Hub moderators manage private Christmas contacts" on public.hub_christmas_2026_contacts for all to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator')));
grant select on public.hub_christmas_2026_submissions to anon,authenticated;
grant insert on public.hub_christmas_2026_submissions,public.hub_christmas_2026_contacts to anon,authenticated;
grant select,insert,update,delete on public.hub_christmas_2026_submissions,public.hub_christmas_2026_contacts to authenticated;
comment on table public.hub_christmas_2026_contacts is 'Private contributor contact details; never expose through public reads.';
